38	function CursorSpotlight() {
39	  const [position, setPosition] = useState({ x: 50, y: 50 });
40	
41	  useEffect(() => {
42	    const handleMouseMove = (e: MouseEvent) => {
43	      setPosition({
44	        x: (e.clientX / window.innerWidth) * 100,
45	        y: (e.clientY / window.innerHeight) * 100,
