```typescript
"use client";

import { useEffect, useRef, useState, useCallback, type RefObject } from "react";
import { useScroll, useSpring, useMotionValueEvent, type MotionValue } from "framer-motion";

export interface ScrollProgressState {
  scrollY: number;
  scrollYProgress: number;
  smoothProgress: number;
}

export interface UseScrollProgressOptions {
  spring?: boolean;
  stiffness?: number;
  damping?: number;
  restDelta?: number;
  throttleMs?: number;
}

export function useScrollProgress(options: UseScrollProgressOptions = {}) {
  const { scrollY, scrollYProgress } = useScroll();
  const smooth = useSpring(scrollYProgress, {
    stiffness: options.stiffness ?? 120,
    damping: options.damping ?? 25,
    restDelta: options.restDelta ?? 0.001,
  });

  const [state, setState] = useState<ScrollProgressState>({
    scrollY: 0,
    scrollYProgress: 0,
    smoothProgress: 0,
  });

  const throttleMs = options.throttleMs ?? 16;
  const lastUpdate = useRef(0);

  const update = useCallback((latest: number, y: number) => {
    const now = performance.now();
    if (now - lastUpdate.current >= throttleMs) {
      lastUpdate.current = now;
      setState({
        scrollY: y,
        scrollYProgress: latest,
        smoothProgress: smooth.get(),
      });
    }
  }, [throttleMs, smooth]);

  useMotionValueEvent(scrollYProgress, "change", (latest) => {
    update(latest, scrollY.get());
  });

  return { ...state, scrollYMotion: scrollY, scrollYProgressMotion: scrollYProgress, smoothProgressMotion: smooth };
}

export interface UseSectionProgressOptions {
  offset?: [string, string];
  spring?: boolean;
}

export function useSectionProgress(
  ref: RefObject<HTMLElement | null>,
  options: UseSectionProgressOptions = {}
): MotionValue<number> {
  const { scrollYProgress } = useScroll({
    target: ref,
    offset: options.offset ?? ["start end", "end start"],
  });

  if (options.spring === false) return scrollYProgress;

  return useSpring(scrollYProgress, {
    stiffness: 100,
    damping: 30,
    restDelta: 0.001,
  });
}
```

