"use client";

import { createContext, useContext, useRef, useMemo, type ReactNode, type RefObject } from "react";
import { useScroll, useSpring, useMotionValueEvent, type MotionValue } from "framer-motion";
import { gsap } from "gsap";
import { ScrollTrigger } from "gsap/ScrollTrigger";
import { useActiveSection } from "../hooks/useScrollProgress";

gsap.registerPlugin(ScrollTrigger);

interface SectionRegistration {
  id: string;
  ref: RefObject<HTMLElement | null>;
}

interface ScrollOrchestrationContextValue {
  scrollYProgress: MotionValue<number>;
  smoothProgress: MotionValue<number>;
  scrollY: MotionValue<number>;
  activeSectionId: string;
  registerSection: (id: string, ref: RefObject<HTMLElement | null>) => void;
}

const ScrollOrchestrationContext = createContext<ScrollOrchestrationContextValue | null>(null);

export function useScrollOrchestration() {
  const ctx = useContext(ScrollOrchestrationContext);
  if (!ctx) throw new Error("useScrollOrchestration must be used within ScrollOrchestrator");
  return ctx;
}

interface ScrollOrchestratorProps {
  children: ReactNode;
  sectionIds?: string[];
  showProgressBar?: boolean;
}

export default function ScrollOrchestrator({ children, sectionIds = [], showProgressBar = true }: ScrollOrchestratorProps) {
  const { scrollY, scrollYProgress } = useScroll();
  const smoothProgress = useSpring(scrollYProgress, {
    stiffness: 120,
    damping: 25,
    restDelta: 0.001,
  });

  const activeSectionId = useActiveSection(sectionIds, 80);
  const sectionsRef = useRef<SectionRegistration[]>([]);

  const registerSection = useCallback((id: string, ref: RefObject<HTMLElement | null>) => {
    sectionsRef.current = [...sectionsRef.current.filter(s => s.id !== id), { id, ref }];
  }, []);

  const value = useMemo(() => ({
    scrollY,
    scrollYProgress,
    smoothProgress,
    activeSectionId,
    registerSection,
  }), [scrollY, scrollYProgress, smoothProgress, activeSectionId, registerSection]);

  return (
    <ScrollOrchestrationContext.Provider value={value}>
      {showProgressBar && <ScrollProgressBar progress={smoothProgress} />}
      {children}
    </ScrollOrchestrationContext.Provider>
  );
}

function ScrollProgressBar({ progress }: { progress: MotionValue<number> }) {
  return (
    <motion.div
      className="fixed top-0 left-0 h-[2px] z-[10000] origin-left"
      style={{
        scaleX: progress,
        background: "linear-gradient(90deg, #00d2ff, #0078ff, #a78bfa)",
      }}
    />
  );
}
