```typescript
"use client";

import { useRef, type ReactNode } from "react";
import { motion, useScroll, useTransform, useSpring, type MotionValue } from "framer-motion";

interface ParallaxLayerProps {
  children: ReactNode;
  speed?: number; // -1 (background) to 1 (foreground)
  yOffset?: number; // max pixels
  opacityRange?: [number, number];
  scaleRange?: [number, number];
  rotateRange?: [number, number];
  className?: string;
  containerRef?: React.RefObject<HTMLElement | null>;
  as?: "div" | "span" | "section";
  spring?: boolean;
}

export default function ParallaxLayer({
  children,
  speed = 0,
  yOffset = 120,
  opacityRange,
  scaleRange,
  rotateRange,
  className = "",
  containerRef,
  as: Tag = "div",
  spring = true,
}: ParallaxLayerProps) {
  const localRef = useRef<HTMLDivElement>(null);
  const ref = containerRef ?? localRef;

  const { scrollYProgress } = useScroll({
    target: ref,
    offset: ["start end", "end start"],
  });

  const rawY = useTransform(scrollYProgress, [0, 1], [yOffset * speed, -yOffset * speed]);
  const y = spring ? useSpring(rawY, { stiffness: 100, damping: 30, restDelta: 0.5 }) : rawY;

  const opacity = opacityRange
    ? useTransform(scrollYProgress, [0, 0.25, 0.75, 1], [opacityRange[0], 1, 1, opacityRange[1]])
    : undefined;

  const scale = scaleRange
    ? useTransform(scrollYProgress, [0, 0.5, 1], [scaleRange[0], 1, scaleRange[1]])
    : undefined;

  const rotate = rotateRange
    ? useTransform(scrollYProgress, [0, 1], [rotateRange[0], rotateRange[1]])
    : undefined;

  const MotionTag = motion[Tag];

  return (
    <MotionTag
      ref={localRef as React.RefObject<HTMLDivElement>}
      className={`will-change-transform ${className}`}
      style={{ y, opacity, scale, rotate }}
    >
      {children}
    </MotionTag>
  );
}
