"use client";

import { motion, type Variants, type Transition } from "framer-motion";
import { type ReactNode } from "react";

type RevealVariant = "fade" | "slide-up" | "slide-down" | "slide-left" | "slide-right" | "zoom" | "mask" | "z-reveal";

interface ScrollRevealProps {
  children: ReactNode;
  variant?: RevealVariant;
  delay?: number;
  duration?: number;
  stagger?: number;
  once?: boolean;
  amount?: number;
  className?: string;
  as?: "div" | "span" | "section" | "article" | "li";
  staggerChildren?: boolean;
  blur?: boolean;
}

const transitionDefaults: Transition = {
  duration: 0.8,
  ease: [0.16, 1, 0.3, 1] as const,
};

function getVariants(variant: RevealVariant, blur: boolean): Variants {
  const hidden = { opacity: 0 };
  const visible = { opacity: 1 };

  switch (variant) {
    case "slide-up":
      return { hidden: { ...hidden, y: 60 }, visible: { ...visible, y: 0 } };
    case "slide-down":
      return { hidden: { ...hidden, y: -60 }, visible: { ...visible, y: 0 } };
    case "slide-left":
      return { hidden: { ...hidden, x: 60 }, visible: { ...visible, x: 0 } };
    case "slide-right":
      return { hidden: { ...hidden, x: -60 }, visible: { ...visible, x: 0 } };
    case "zoom":
      return { hidden: { ...hidden, scale: 0.88 }, visible: { ...visible, scale: 1 } };
    case "mask":
      return {
        hidden: { ...hidden, clipPath: "inset(0 100% 0 0)" },
        visible: { ...visible, clipPath: "inset(0 0% 0 0)" },
      };
    case "z-reveal":
      return {
        hidden: { ...hidden, scale: 0.92, z: -60, filter: blur ? "blur(8px)" : "blur(0px)" },
        visible: { ...visible, scale: 1, z: 0, filter: "blur(0px)" },
      };
    default:
      return { hidden, visible };
  }
}

