export default function ScrollReveal({
  children,
  variant = "fade",
  delay = 0,
  duration = 0.8,
  stagger = 0.1,
  once = true,
  amount = 0.25,
  className = "",
  as: Tag = "div",
  staggerChildren = false,
  blur = true,
}: ScrollRevealProps) {
  const MotionTag = motion[Tag];
  const variants = getVariants(variant, blur);

  if (staggerChildren) {
    return (
      <MotionTag
        className={className}
        initial="hidden"
        whileInView="visible"
        viewport={{ once, amount }}
        variants={{
          hidden: {},
          visible: {
            transition: {
              staggerChildren: stagger,
              delayChildren: delay,
            },
          },
        }}
      >
        {children}
      </MotionTag>
    );
  }

  return (
    <MotionTag
      className={className}
      variants={variants}
      initial="hidden"
      whileInView="visible"
      viewport={{ once, amount }}
      transition={{ ...transitionDefaults, duration, delay }}
    >
      {children}
    </MotionTag>
  );
}

export function ScrollRevealItem({
  children,
  variant = "slide-up",
  className = "",
  delay = 0,
