}: {
  children: ReactNode;
  variant?: RevealVariant;
  className?: string;
  delay?: number;
  duration?: number;
  blur?: boolean;
}) {
  const variants = getVariants(variant, blur);
  return (
    <motion.div
      className={className}
      variants={variants}
      transition={{ ...transitionDefaults, duration, delay }}
    >
      {children}
    </motion.div>
  );
