"use client";

import { useEffect, useRef } from "react";
import { gsap } from "gsap";
import { ScrollTrigger } from "gsap/ScrollTrigger";

gsap.registerPlugin(ScrollTrigger);

interface UseScrollTriggerOptions {
  trigger: React.RefObject<HTMLElement | null>;
  start?: string;
  end?: string;
  scrub?: boolean | number;
  pin?: boolean;
  markers?: boolean;
  onUpdate?: (self: ScrollTrigger) => void;
  animation?: gsap.core.Timeline | gsap.core.Tween;
}

export function useScrollTrigger(options: UseScrollTriggerOptions) {
  const triggerRef = options.trigger;

  useEffect(() => {
    if (!triggerRef.current) return;

    const st = ScrollTrigger.create({
      trigger: triggerRef.current,
      start: options.start ?? "top 80%",
      end: options.end ?? "bottom 20%",
      scrub: options.scrub ?? false,
      pin: options.pin ?? false,
      markers: options.marketers ?? false,
      animation: options.animation,
      onUpdate: options.onUpdate,
    });

    return () => {
      st.kill();
    };
  }, [triggerRef, options.start, options.end, options.scrub, options.pin, options.markers, options.animation, options.onUpdate]);
}
