  progress,
}: {
  progress: MotionValue<number>;
}) {
  return (
    <motion.div
      className="fixed top-0 left-0 h-[2px] z-[10000] origin-left pointer-events-none"
      style={{
        scaleX: progress,
        background: "linear-gradient(90deg, #00d2ff, #0078ff, #a78bfa)",
      }}
    />
  );
}

interface SectionProps {
  id: string;
  children: ReactNode;
  className?: string;
  register?: boolean;
}

