  as: Tag = "div",
  spring = true,
  springConfig = { stiffness: 100, damping: 30, restDelta: 0.5 },
  style,
}: ParallaxLayerProps) {
  const localRef = useRef<HTMLDivElement>(null);
  const targetRef = containerRef ?? localRef;

  const { scrollYProgress } = useScroll({
    target: targetRef,
    offset: ["start end", "end start"],
  });

  const rawY = useTransform(
    scrollYProgress,
    [0, 1],
    [yOffset * speed, -yOffset * speed]
  );
  const y: MotionValue<number> = spring
    ? useSpring(rawY, springConfig)
    : rawY;

  const opacity = opacityRange
    ? useTransform(scrollYProgress, [0, 0.25, 0.75, 1], opacityRange)
    : undefined;

  const scale = scaleRange
    ? useTransform(scrollYProgress, [0, 0.5, 1], scaleRange)
    : undefined;

  const rotate = rotateRange
    ? useTransform(scrollYProgress, [0, 1], rotateRange)
    : undefined;

  const MotionTag = motion[Tag] as ElementType;

  return (
    <MotionTag
      ref={localRef}
      className={`will-change-transform transform-gpu ${className}`}
      style={{
        y,
        opacity,
        scale,
        rotate,
        ...style,
      }}
    >
      {children}
    </MotionTag>
  );
}

