"use client";

import { useEffect, useState } from "react";
import { useMotionValueEvent } from "framer-motion";
import ScrollOrchestrator, {
  useScrollOrchestration,
} from "../components/ScrollOrchestrator";
import PortfolioCanvas from "../components/PortfolioCanvas";
import HeroSection from "../components/sections/HeroSection";
import AboutSection from "../components/sections/AboutSection";
import ExperienceSection from "../components/sections/ExperienceSection";
import SkillsSection from "../components/sections/SkillsSection";
import CertsSection from "../components/sections/CertsSection";
import ContactSection from "../components/sections/ContactSection";

const navItems = [
  { id: "hero", label: "Intro" },
  { id: "about", label: "About" },
  { id: "experience", label: "Experience" },
  { id: "skills", label: "Skills" },
  { id: "certs", label: "Certs" },
  { id: "contact", label: "Contact" },
];

const sectionIds = navItems.map((item) => item.id);

function CursorSpotlight() {
  const [position, setPosition] = useState({ x: 50, y: 50 });

  useEffect(() => {
    const handleMouseMove = (e: MouseEvent) => {
      setPosition({
        x: (e.clientX / window.innerWidth) * 100,
        y: (e.clientY / window.innerHeight) * 100,
      });
    };

    window.addEventListener("mousemove", handleMouseMove);
    return () => window.removeEventListener("mousemove", handleMouseMove);
  }, []);

  return (
    <div
      className="cursor-spotlight hide-mobile"
      style={
        {
          "--cursor-x": `${position.x}%`,
          "--cursor-y": `${position.y}%`,
        } as React.CSSProperties
      }
    />
  );
}

function SideDots() {
  const { activeSectionId } = useScrollOrchestration();

  return (
    <div className="fixed right-6 md:right-10 top-1/2 -translate-y-1/2 z-40 hidden lg:flex flex-col gap-5">
      {navItems.map((item) => (
        <a
          key={item.id}
          href={`#${item.id}`}
          className="group flex items-center justify-end gap-4"
        >
          <span
            className={`text-[10px] font-mono tracking-widest transition-all duration-300 uppercase ${
              activeSectionId === item.id
                ? "text-white/80"
                : "text-white/0 group-hover:text-white/40 translate-x-4 group-hover:translate-x-0"
            }`}
          >
            {item.label}
          </span>
          <div
            className={`w-1 transition-all duration-500 rounded-full ${
              activeSectionId === item.id
                ? "h-8 bg-white"
                : "h-2 bg-white/20 group-hover:bg-white/40 group-hover:h-4"
            }`}
          />
        </a>
      ))}
    </div>
  );
}

function ScrollBackedCanvas() {
  const { smoothProgress } = useScrollOrchestration();
  const [scrollProgress, setScrollProgress] = useState(0);

  useMotionValueEvent(smoothProgress, "change", (latest) => {
    setScrollProgress(latest);
  });

  return (
    <div className="fixed inset-0 z-0">
      <PortfolioCanvas scrollProgress={scrollProgress} />
    </div>
  );
}

export default function Home() {
  return (
    <ScrollOrchestrator sectionIds={sectionIds}>
      <main className="relative w-full bg-[#03040b] overflow-x-hidden">
        <CursorSpotlight />
        <SideDots />
        <ScrollBackedCanvas />

        <div className="relative z-10">
          <HeroSection />
          <AboutSection />
          <ExperienceSection />
          <SkillsSection />
          <CertsSection />
          <ContactSection />
        </div>
      </main>
    </ScrollOrchestrator>
  );
}

