              }}
              className="absolute -bottom-4 -left-6 md:left-2 w-12 h-12 opacity-70"
            >
              <GlassCard
                className="w-full h-full flex items-center justify-center"
                accentColor="rgba(255, 54, 0, 0.15)"
                hover3d={false}
              >
                <Award className="w-5 h-5 text-databricks" />
              </GlassCard>
            </motion.div>
          </div>

          {/* Text content */}
          <div className="order-1 lg:order-2">
            <ScrollReveal variant="slide-up" delay={0.1}>
              <span className="eyebrow mb-4 block">Über mich</span>
            </ScrollReveal>

            <h2 className="text-3xl sm:text-4xl md:text-5xl lg:text-6xl font-bold tracking-tighter text-white mb-6 lg:mb-8">
              <AnimatedText
                text="Mensch hinter den Daten"
                delay={0}
                stagger={0.03}
              />
            </h2>

            <ScrollReveal variant="slide-up" delay={0.2}>
              <div className="space-y-5 text-white/55 text-base md:text-lg leading-relaxed max-w-xl mb-10 lg:mb-12">
                <p>
                  Als Senior Cloud Data Engineer verbinde ich technische Tiefe
                  mit Business-Verständnis. Ich baue skalierbare
                  Daten-Ökosysteme in Azure und Google Cloud.
                </p>
                <p>
                  Von Data Warehouses über Databricks-Pipelines bis hin zu
                  KI-Governance – ich entwickle Lösungen, die Unternehmen
                  befähigen, Daten als Wettbewerbsvorteil zu nutzen.
                </p>
              </div>
            </ScrollReveal>

            {/* Milestone sub-grid */}
            <div ref={statsRef}>
              <ZReveal
                staggerChildren
                stagger={0.12}
                delay={0.3}
                className="grid grid-cols-1 sm:grid-cols-3 gap-5 md:gap-6"
              >
                {stats.map((stat, i) => (
                  <ZRevealItem key={i}>
                    <GlassCard
                      className="text-center h-full"
                      accentColor="rgba(0, 210, 255, 0.18)"
                      hover3d={false}
                    >
                      <div className="py-5 px-3">
                        <stat.icon className="w-6 h-6 mx-auto mb-4 text-azure" />
